class SnippetAssetUpdateCheck
{
    public function __construct(public readonly SnippetAssetUpdateParams $input, public readonly SnippetAsset $current)
    {
    }
    public function reject(RuntimeException|ConstraintFail $fail): void
    {
        if ($fail instanceof ConstraintFail) {
            throw ConstraintException::ofFail($fail);
        } else {
            throw $fail;
        }
    }
}
